const lines = String(msg.payload ?? "")
    .replace(/\r/g, "")
    .split("\n")
    .map(line => line.trim())
    .filter(Boolean);

if (
    lines.length < 3 ||
    lines[0] !== "START" ||
    lines[lines.length - 1] !== "STOP"
) {
    node.error(
        "Acquisition payload is missing START or STOP",
        msg
    );

    return null;
}

msg.first = lines[0];
msg.last = lines[lines.length - 1];

// Intentionally remove START and STOP here
lines.shift();
lines.pop();

msg.payload = lines.join("\n");

return msg;

let lines = String(msg.payload ?? "")
    .replace(/\r/g, "")
    .split("\n")
    .map(line => line.trim())
    .filter(line => line.length > 0);

if (lines.length > 0 && lines[0].replace(/\s/g, "").toUpperCase() === "V,I") {
    lines.shift();
}

if (lines.length === 0) {
    node.error("Acquisition contains no samples", msg);
    return null;
}

const normalized = [];
for (let index = 0; index < lines.length; index++) {
    const parts = lines[index].split(",").map(value => value.trim());
    if (parts.length !== 2 || parts[0] === "" || parts[1] === "") {
        node.error(`Invalid V,I sample at row ${index + 1}: ${lines[index]}`, msg);
        return null;
    }

    const voltage = Number(parts[0]);
    const current = Number(parts[1]);
    if (!Number.isFinite(voltage) || !Number.isFinite(current)) {
        node.error(`Non-numeric V,I sample at row ${index + 1}: ${lines[index]}`, msg);
        return null;
    }

    normalized.push(`${parts[0]},${parts[1]}`);
}

msg.payload = normalized.join("\n");
msg.sample_count = normalized.length;
return msg;

const device = String(msg.device_id || msg.device_name || "unknown").trim();
const acquired = new Date(msg.last_seen || Date.now());

if (Number.isNaN(acquired.getTime())) {
    node.error("Invalid acquisition timestamp", msg);
    return null;
}

const iso = acquired.toISOString();
const filenameTimestamp = iso
    .replace("T", "_")
    .replace(/[:.]/g, "-")
    .replace(/Z$/, "");
const safeDevice = device.replace(/[^A-Za-z0-9_.-]/g, "_");
const csvRows = String(msg.payload ?? "").trim();

const lastTest = {
    data: csvRows ? `V,I\n${csvRows}\n` : "V,I\n",
    name: `${safeDevice}_${filenameTimestamp}`,
    device_name: device,
    acquired_at_utc: iso,
    sample_count: Number(msg.sample_count) || 0
};

global.set("last_test", lastTest);
return msg;

let chunks = msg.payload;
let light = null;

if (!Array.isArray(chunks)) {
    node.error("msg.payload must be an array of strings", msg);
    msg.ok = false;
    return null;
}

let parsed;

try {
    parsed = chunks.map(chunk => {
        chunk = Buffer.isBuffer(chunk)
            ? chunk.toString("utf8")
            : String(chunk);

        const match = chunk.match(/^\s*cnt=(\d+)/i);

        if (!match) {
            throw new Error(
                "Missing cnt= value at the start of a chunk"
            );
        }

        return {
            cnt: Number(match[1]),
            text: chunk
        };
    });
} catch (error) {
    node.error(error.message, msg);
    msg.ok = false;
    return null;
}

// Sort chunks from lowest to highest cnt
parsed.sort((a, b) => a.cnt - b.cnt);

// Verify continuous cnt sequence
for (let i = 0; i < parsed.length; i++) {
    if (parsed[i].cnt !== i) {
        node.error(
            `Missing or unexpected chunk: expected cnt=${i}, ` +
            `received cnt=${parsed[i].cnt}`,
            msg
        );

        msg.ok = false;
        return null;
    }
}

// STOP must be contained in the highest-numbered chunk
const lastChunk = parsed[parsed.length - 1];

const lastChunkHasStop =
    /(?:^|\r?\n)\s*STOP\s*(?:\r?\n|$)/i.test(lastChunk.text);

if (!lastChunkHasStop) {
    node.error(
        `The final chunk cnt=${lastChunk.cnt} does not contain STOP. ` +
        `The Join node probably completed before receiving the last chunk.`,
        msg
    );

    msg.ok = false;
    return null;
}

const outputLines = [];

for (let index = 0; index < parsed.length; index++) {
    let lines = parsed[index].text
        .replace(/\r/g, "")
        .split("\n");

    // Remove cnt=... line
    lines.shift();

    for (const line of lines) {
        const value = line.trim();

        if (!value) {
            continue;
        }

        // Extract and remove LIGHT=...
        const lightMatch = value.match(/^LIGHT\s*=\s*(.*)$/i);

        if (lightMatch) {
            light = lightMatch[1].trim();
            continue;
        }

        // Remove duplicated headers only from later chunks
        if (
            index > 0 &&
            (value === "START" || value === "V,I")
        ) {
            continue;
        }

        // This includes STOP from the final chunk
        outputLines.push(value);
    }
}

msg.payload = outputLines.join("\n");
msg.light = light;
msg.lightValue = light !== null
    ? Number.parseFloat(light)
    : null;

msg.chunk_count = parsed.length;
msg.last_cnt = lastChunk.cnt;
msg.ok = true;

return msg;

if (Number.isInteger(msg.sample_count)) {
    msg.payload = msg.sample_count;
} else {
    msg.payload = String(msg.payload ?? "")
        .split(/\r?\n/)
        .filter(line => line.trim().length > 0)
        .length;
}
return msg;

// Convert Buffer or other payload types to string
const payload = Buffer.isBuffer(msg.payload)
    ? msg.payload.toString("utf8")
    : String(msg.payload ?? "");

msg.payload = payload;

// Tell the Join node to emit the accumulated array
// when the final chunk containing STOP arrives.
if (/(?:^|\r?\n)\s*STOP\s*(?:\r?\n|$)/i.test(payload)) {
    msg.complete = true;
}

return msg;

const lastTest = global.get("last_test");

if (!lastTest) {
    msg.statusCode = 404;
    msg.payload = "No acquisition is available for download.";
    msg.headers = {
        "Content-Type": "text/plain; charset=utf-8",
        "Cache-Control": "no-store"
    };
    return msg;
}

const name = String(lastTest.name || "last_acquisition")
    .replace(/[^A-Za-z0-9_.-]/g, "_");
let data = String(lastTest.data || "");
if (!/^V,I(?:\r?\n|$)/.test(data)) {
    data = `V,I\n${data}`;
}

msg.payload = data;
msg.headers = {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": `attachment; filename="${name}.csv"`,
    "Cache-Control": "no-store"
};
return msg;

msg.payload = msg.payload.map((obj,index) => ({
    ...obj,
    sn:index
}));
return msg;

let V = Number(msg.payload.split(",")[0].trim());
let I = Number(msg.payload.split(",")[1].trim());
let P = V * I;
P = Number(P.toFixed(3));

msg.payload = {
    v: V,
    i: I,
    p: P
};

return msg;

const samples = Array.isArray(msg.payload) ? msg.payload : [];
const splitIndex = Math.ceil(samples.length / 2);

msg.payload = samples.map((element, index) => ({
    series: index < splitIndex ? "OC_to_SC" : "SC_to_OC",
    x: element.v,
    y: element.i
}));
return msg;

const samples = Array.isArray(msg.payload) ? msg.payload : [];
const splitIndex = Math.ceil(samples.length / 2);

msg.payload = samples.map((element, index) => ({
    series: index < splitIndex ? "OC_to_SC" : "SC_to_OC",
    x: element.v,
    y: element.p
}));
return msg;

const deviceName = String(
    msg.device_id || msg.device_name || msg.device || "dummy"
).trim();

if (!deviceName) {
    node.error("Cannot save an acquisition without a device name", msg);
    return null;
}

const acquired = new Date(msg.last_seen || Date.now());
if (Number.isNaN(acquired.getTime())) {
    node.error("Cannot save an acquisition with an invalid timestamp", msg);
    return null;
}

const rawLines = String(msg.payload ?? "")
    .replace(/\r/g, "")
    .split("\n")
    .map(line => line.trim())
    .filter(line => line.length > 0)
    .filter(line => {
        const marker = line.replace(/\s/g, "").toUpperCase();
        return marker !== "START" && marker !== "STOP" && marker !== "V,I";
    });

if (rawLines.length === 0) {
    node.error("Cannot save an acquisition without samples", msg);
    return null;
}

const numberPattern = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
const decimalLimit = 9999999999.999999;
const samples = [];

for (let index = 0; index < rawLines.length; index++) {
    const parts = rawLines[index].split(",").map(value => value.trim());
    if (parts.length !== 2 || !numberPattern.test(parts[0]) || !numberPattern.test(parts[1])) {
        node.error(`Invalid V,I sample at row ${index + 1}: ${rawLines[index]}`, msg);
        return null;
    }

    const valueX = Number(parts[0]);
    const valueY = Number(parts[1]);
    if (!Number.isFinite(valueX) || !Number.isFinite(valueY)) {
        node.error(`Non-finite V,I sample at row ${index + 1}`, msg);
        return null;
    }
    if (Math.abs(valueX) > decimalLimit || Math.abs(valueY) > decimalLimit) {
        node.error(`V,I sample at row ${index + 1} exceeds DECIMAL(16,6)`, msg);
        return null;
    }

    samples.push([parts[0], parts[1]]);
}

const acquiredAtUtc = acquired.toISOString().slice(0, 23).replace("T", " ");
const sql = [];
const params = [];

// Remove abandoned partial acquisitions from previous failed writes.
sql.push(
    "DELETE FROM `acquisitions` " +
    "WHERE `sample_count` = 0 " +
    "AND `created_at` < CURRENT_TIMESTAMP - INTERVAL 1 DAY"
);

// Create the device once, or retrieve its existing id through LAST_INSERT_ID().
sql.push(
    "INSERT INTO `devices` (`device_name`) VALUES (?) " +
    "ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`)"
);
params.push(deviceName);
sql.push("SET @device_id := LAST_INSERT_ID()");

// Serialize identifier allocation per device. The lock is released before the
// larger sample insert begins.
sql.push(
    "SET @lock_acquired := " +
    "GET_LOCK(CONCAT('iv_acquisition_', @device_id), 10)"
);
sql.push(
    "SET @acquisition_identifier := (" +
    "SELECT COALESCE(MAX(a.`acquisition_identifier`), 0) + 1 " +
    "FROM `acquisitions` AS a WHERE a.`device_id` = @device_id)"
);

// sample_count=0 is a completion marker: historical queries ignore the row
// until all child samples have been inserted successfully.
sql.push(
    "INSERT IGNORE INTO `acquisitions` " +
    "(`device_id`, `acquisition_identifier`, `acquired_at_utc`, `sample_count`) " +
    "SELECT @device_id, @acquisition_identifier, ?, 0 " +
    "WHERE @lock_acquired = 1"
);
params.push(acquiredAtUtc);
sql.push("SET @acquisition_id := IF(ROW_COUNT() = 1, LAST_INSERT_ID(), NULL)");
sql.push("DO RELEASE_LOCK(CONCAT('iv_acquisition_', @device_id))");

const batchSize = 500;
for (let start = 0; start < samples.length; start += batchSize) {
    const batch = samples.slice(start, start + batchSize);
    const values = [];

    for (let offset = 0; offset < batch.length; offset++) {
        const sampleIndex = start + offset;
        values.push(`(@acquisition_id, ${sampleIndex}, ?, ?)`);
        params.push(batch[offset][0], batch[offset][1]);
    }

    sql.push(
        "INSERT INTO `acquisition_samples` " +
        "(`acquisition_id`, `sample_index`, `value_x`, `value_y`) VALUES " +
        values.join(", ")
    );
}

sql.push(
    "UPDATE `acquisitions` SET `sample_count` = ? " +
    "WHERE `id` = @acquisition_id"
);
params.push(samples.length);

sql.push(
    "SELECT a.`id` AS `acquisition_id`, " +
    "a.`acquisition_identifier`, d.`device_name`, " +
    "DATE_FORMAT(a.`acquired_at_utc`, '%Y-%m-%d %H:%i:%s') AS `acquired_at_utc`, " +
    "a.`sample_count` " +
    "FROM `acquisitions` AS a " +
    "JOIN `devices` AS d ON d.`id` = a.`device_id` " +
    "WHERE a.`id` = @acquisition_id"
);

msg.topic = sql.join(";\n") + ";";
msg.payload = params;
msg.sample_count = samples.length;
msg.save_info = {
    device_name: deviceName,
    acquired_at_utc: acquired.toISOString(),
    sample_count: samples.length
};
return msg;

const deviceName = String(msg.device || msg.payload || "").trim();
if (!deviceName) {
    node.error("Select a device before loading acquisitions", msg);
    return null;
}

msg.device = deviceName;
msg.topic = [
    "SELECT",
    "    a.`id`,",
    "    a.`acquisition_identifier`,",
    "    DATE_FORMAT(a.`acquired_at_utc`, '%Y-%m-%d %H:%i:%s') AS `acquired_at_utc`,",
    "    CONCAT(",
    "        a.`acquisition_identifier`, ' : ',",
    "        DATE_FORMAT(a.`acquired_at_utc`, '%Y-%m-%d %H:%i:%s')",
    "    ) AS `opt`",
    "FROM `acquisitions` AS a",
    "JOIN `devices` AS d ON d.`id` = a.`device_id`",
    "WHERE d.`device_name` = ? AND a.`sample_count` > 0",
    "ORDER BY a.`acquired_at_utc` DESC, a.`id` DESC"
].join("\n") + ";";
msg.payload = [deviceName];
return msg;

let options = [];
for (let index = 0; index < msg.payload.length; index++) {
    const element = msg.payload[index];
    options.push(element.opt);
}
msg.options = options;
return msg;

const selected = String(msg.payload ?? "");
const match = selected.match(/^\s*(\d+)\s*:/);
if (!match) {
    node.error(`Invalid acquisition selection: ${selected}`, msg);
    return null;
}

const acquisitionId = Number(match[1]);
if (!Number.isSafeInteger(acquisitionId) || acquisitionId <= 0) {
    node.error(`Invalid acquisition id: ${match[1]}`, msg);
    return null;
}

msg.id = acquisitionId;
return msg;

const acquisitionId = Number(msg.id);
if (!Number.isSafeInteger(acquisitionId) || acquisitionId <= 0) {
    node.error("A valid acquisition id is required", msg);
    return null;
}

msg.topic = [
    "SELECT",
    "    a.`id` AS `acquisition_id`,",
    "    a.`acquisition_identifier`,",
    "    DATE_FORMAT(a.`acquired_at_utc`, '%Y-%m-%d %H:%i:%s') AS `acquired_at_utc`,",
    "    d.`device_name`,",
    "    a.`sample_count`,",
    "    s.`sample_index`,",
    "    CAST(s.`value_x` AS CHAR) AS `value_x`,",
    "    CAST(s.`value_y` AS CHAR) AS `value_y`",
    "FROM `acquisitions` AS a",
    "JOIN `devices` AS d ON d.`id` = a.`device_id`",
    "JOIN `acquisition_samples` AS s ON s.`acquisition_id` = a.`id`",
    "WHERE a.`id` = ? AND a.`sample_count` > 0",
    "ORDER BY s.`sample_index`"
].join("\n") + ";";
msg.payload = [acquisitionId];
return msg;

msg.topic = [
    "SELECT d.`device_name` AS `device`",
    "FROM `devices` AS d",
    "WHERE EXISTS (",
    "    SELECT 1 FROM `acquisitions` AS a",
    "    WHERE a.`device_id` = d.`id` AND a.`sample_count` > 0",
    ")",
    "ORDER BY d.`device_name`"
].join("\n") + ";";
msg.payload = [];
return msg;

let options = [];
for (let index = 0; index < msg.payload.length; index++) {
    const element = msg.payload[index];
    options.push(element.device);
}
msg.options = options;
return msg;

const selectedTest = global.get("selected_test");

if (!selectedTest) {
    msg.statusCode = 404;
    msg.payload = "No historical acquisition is selected.";
    msg.headers = {
        "Content-Type": "text/plain; charset=utf-8",
        "Cache-Control": "no-store"
    };
    return msg;
}

const name = String(selectedTest.name || "selected_acquisition")
    .replace(/[^A-Za-z0-9_.-]/g, "_");
let data = String(selectedTest.data || "");
if (!/^V,I(?:\r?\n|$)/.test(data)) {
    data = `V,I\n${data}`;
}

msg.payload = data;
msg.headers = {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": `attachment; filename="${name}.csv"`,
    "Cache-Control": "no-store"
};
return msg;

const rows = msg.payload;
if (!Array.isArray(rows) || rows.length === 0) {
    node.error("The selected acquisition has no stored samples", msg);
    return null;
}

const first = rows[0];
const expectedCount = Number(first.sample_count);
if (Number.isFinite(expectedCount) && expectedCount !== rows.length) {
    node.warn(
        `Acquisition ${first.acquisition_id} declares ${expectedCount} samples but ${rows.length} were loaded`
    );
}

const data = rows
    .map(row => `${row.value_x},${row.value_y}`)
    .join("\n");

const acquisitionId = Number(first.acquisition_id);
const identifier = Number(first.acquisition_identifier);
const device = String(first.device_name || "unknown");
const acquiredAtUtc = String(first.acquired_at_utc || "");
const safeDevice = device.replace(/[^A-Za-z0-9_.-]/g, "_");
const safeTimestamp = acquiredAtUtc
    .replace("T", "_")
    .replace(/[:.]/g, "-")
    .replace(/Z$/, "");
const name = `id${identifier}_${safeDevice}_${safeTimestamp}`;

const selectedTest = {
    id: acquisitionId,
    acquisition_identifier: identifier,
    device_name: device,
    acquired_at_utc: acquiredAtUtc,
    sample_count: rows.length,
    data,
    name
};

global.set("selected_test", selectedTest);
msg.id = acquisitionId;
msg.acquisition_identifier = identifier;
msg.device = device;
msg.timestamp = acquiredAtUtc;
msg.sample_count = rows.length;
msg.payload = data;
return msg;

const selectedTest = global.get("selected_test");
const acquisitionId = Number(selectedTest && selectedTest.id);

if (!Number.isSafeInteger(acquisitionId) || acquisitionId <= 0) {
