const samples = Array.isArray(msg.payload) ? msg.payload : [];
const splitIndex = Math.ceil(samples.length / 2);

msg.payload = samples.map((element, index) => ({
    series: index < splitIndex ? "OC_to_SC" : "SC_to_OC",
    x: element.v,
    y: element.p
}));
return msg;

const data = msg.payload;

if (!Array.isArray(data) || data.length === 0) {
    node.warn("msg.payload must be a non-empty array");
    return null;
}

// Filter settings
const medianWindow = 7;   // Must preferably be odd
const averageWindow = 15;

// Extract current values
const current = data.map(point => Number(point.i));

// Median function
function median(values) {
    const sorted = [...values].sort((a, b) => a - b);
    const middle = Math.floor(sorted.length / 2);

    if (sorted.length % 2 === 0) {
        return (sorted[middle - 1] + sorted[middle]) / 2;
    }

    return sorted[middle];
}

// 1. Median filter for spike removal
const medianFiltered = current.map((value, index) => {
    const halfWindow = Math.floor(medianWindow / 2);

    const start = Math.max(0, index - halfWindow);
    const end = Math.min(current.length, index + halfWindow + 1);

    return median(current.slice(start, end));
});

// 2. Moving-average filter for light smoothing
const filteredCurrent = medianFiltered.map((value, index) => {
    const start = Math.max(0, index - averageWindow + 1);
    const window = medianFiltered.slice(start, index + 1);

    return window.reduce((sum, sample) => sum + sample, 0) / window.length;
});

// Rebuild the array
msg.payload = data.map((point, index) => ({
    ...point,
    i_raw: point.i,
    i: filteredCurrent[index],
    p_raw: point.p,
    p: Number(point.v) * filteredCurrent[index]
}));

return msg;

msg.timestamp = Number(msg.payload.split(";")[0]);
msg.irradiance = parseFloat(msg.payload.split(";")[1]);
return msg;

